package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_join_TriageGen0Test {

    @Test
    public void testJoin_NullArray() {
        assertNull("Should return null when array is null", 
            StringUtils.join(null, ',', 0, 0));
    }

    @Test
    public void testJoin_EmptyRange() {
        Object[] array = {"a", "b", "c"};
        // endIndex <= startIndex
        assertEquals("Should return empty string when endIndex <= startIndex", 
            "", StringUtils.join(array, ',', 1, 1));
        assertEquals("Should return empty string when endIndex < startIndex", 
            "", StringUtils.join(array, ',', 2, 1));
    }

    @Test
    public void testJoin_SingleElement() {
        Object[] array = {"a", "b", "c"};
        assertEquals("Should return single element without separator", 
            "b", StringUtils.join(array, ',', 1, 2));
    }

    @Test
    public void testJoin_MultipleElements() {
        Object[] array = {"a", "b", "c", "d"};
        assertEquals("Should join multiple elements with separator", 
            "b,c,d", StringUtils.join(array, ',', 1, 4));
    }

    @Test
    public void testJoin_WithNullElements() {
        Object[] array = {"a", null, "c", null};
        // The logic: if array[i] != null, append it. If null, it just skips appending the content but still appends the separator if i > startIndex.
        // Let's trace: 
        // i=0: buf="a"
        // i=1: i > 0 -> buf="a,". array[1] is null -> buf="a,"
        // i=2: i > 0 -> buf="a,,c"
        // i=3: i > 0 -> buf="a,,c,". array[3] is null -> buf="a,,c,"
        // Wait, looking at code: if (array[i] != null) { buf.append(array[i]); }
        // If array[1] is null, it appends the separator but not the element.
        assertEquals("Should handle null elements by skipping their value but keeping separators", 
            "a,,c,", StringUtils.join(array, ',', 0, 4));
    }

    @Test
    public void testJoin_FirstElementNull() {
        Object[] array = {null, "b", "c"};
        // StringBuilder initialization uses array[startIndex] length. 
        // If array[0] is null, capacity is 16.
        assertEquals("Should handle null as the first element", 
            ",b,c", StringUtils.join(array, ',', 0, 3));
    }

    @Test
    public void testJoin_AllNullElements() {
        Object[] array = {null, null, null};
        assertEquals("Should handle all null elements", 
            ",,", StringUtils.join(array, ',', 0, 3));
    }

    @Test
    public void testJoin_DifferentTypes() {
        Object[] array = {1, "two", 3.0};
        assertEquals("Should handle different object types via toString()", 
            "1,two,3.0", StringUtils.join(array, ',', 0, 3));
    }

    @Test
    public void testJoin_LargeRange() {
        Object[] array = {"1", "2", "3", "4", "5"};
        assertEquals("Should work with specific range", 
            "2,3,4", StringUtils.join(array, '-', 1, 4));
    }
}
